// Support desk: ticket list and the open conversation side by side (stacked on phones), status tiles that filter,
// bulk status changes with typed confirmation, and a reply composer with canned openers and Ctrl+Enter.
(() => {
  'use strict';
  const $=s=>document.querySelector(s),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fa=n=>Number(n||0).toLocaleString('fa-IR');
  const statuses={open:'در انتظار پاسخ',answered:'پاسخ داده شده',closed:'بسته شده'};
  const categories={sales:'خرید و اشتراک',account:'حساب',payment:'پرداخت',editor:'ویرایشگر',publication:'انتشار',other:'سایر'};
  const departments={sales:['فروش','tag'],finance:['مالی','receipt'],technical:['فنی','settings'],account:['حساب کاربری','user'],general:['عمومی','mail']};
  const toman=n=>fa(n)+' تومان',it=n=>fa(n)+' It';
  const date=n=>new Date(Number(n)).toLocaleString('fa-IR',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Tehran'});
  const ago=n=>{const s=Math.max(0,(Date.now()-Number(n))/1000);if(s<60)return 'همین حالا';if(s<3600)return fa(Math.floor(s/60))+' دقیقه پیش';if(s<86400)return fa(Math.floor(s/3600))+' ساعت پیش';if(s<604800)return fa(Math.floor(s/86400))+' روز پیش';return new Date(Number(n)).toLocaleDateString('fa-IR',{dateStyle:'medium',timeZone:'Asia/Tehran'});};
  const icon=name=>window.RI?.icon(name)||'';
  const canned=[['سلام','سلام، وقت شما بخیر. ممنون که پیام دادید.\n'],['شمارهٔ فاکتور','برای پیگیری پرداخت، لطفاً شمارهٔ فاکتور یا کد رهگیری بانک را بفرستید. رمز کارت یا کد پیامکی را هرگز نفرستید.'],['تصویر خطا','اگر ممکن است، تصویری از صفحه هنگام خطا پیوست کنید تا دقیق‌تر بررسی کنیم.'],['حل شد','مشکل برطرف شد. اگر دوباره پیش آمد، در همین گفت‌وگو بنویسید.']];
  let owner,admin=false,page=1,serial=0,ticket=null,replyId=null,busy=false,rows=[],total=0,summary=null,department='',escalated=false,mode='reply';
  const workspace=$('#workspace'),filters=$('#filters'),feedback=$('#feedback');
  function icons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>{el.insertAdjacentHTML('afterbegin',icon(el.dataset.icon));el.removeAttribute('data-icon');});}
  async function request(route,data){
    const response=await fetch('/api/dashboard/support'+route,{method:data?'POST':'GET',headers:{'X-ResumeIt-Owner':owner,...(data?{'Content-Type':'application/json'}:{})},body:data?JSON.stringify(data):undefined,signal:AbortSignal.timeout(20000)});
    const result=await response.json();if(!response.ok)throw Error(result.error||'اطلاعات دریافت نشد');return result;
  }
  function error(e){feedback.textContent=e.name==='TimeoutError'?'دریافت اطلاعات طول کشید؛ دوباره تلاش کن.':e.message;feedback.dataset.kind='error';}
  function note(text){feedback.textContent=text;feedback.dataset.kind='ok';}

  // Desk frame: list column and conversation column; the list stays put while conversations change.
  function frame(){if(!workspace.querySelector('.desk-list'))workspace.innerHTML='<section class="desk-list" aria-label="فهرست گفت‌وگوها"></section><section class="desk-thread" aria-live="polite"></section>';return {list:workspace.querySelector('.desk-list'),thread:workspace.querySelector('.desk-thread')};}
  function paintSummary(){
    const current=filters.elements.status.value;
    $('#summary').innerHTML=[['','total','همهٔ تیکت‌ها','mail'],['open','open','منتظر پاسخ شما','clock'],['answered','answered','پاسخ داده شده','check'],['closed','closed','بسته شده','lock']].map(([value,key,label,glyph])=>'<button type="button" class="stat stat--'+key+'" data-filter="'+value+'" aria-pressed="'+(current===value)+'"><span class="stat__icon">'+icon(glyph)+'</span><span class="stat__label">'+label+'</span><strong>'+fa(summary?.[key])+'</strong></button>').join('');
    const badge=$('#menu-open');if(badge){badge.hidden=!summary?.open;badge.textContent=fa(summary?.open);}
    const counts=summary?.departments||{},open=Object.values(counts).reduce((a,b)=>a+b,0);
    $('#departments').innerHTML='<button type="button" data-dept="" aria-pressed="'+(!department&&!escalated)+'">'+icon('menu')+'همهٔ بخش‌ها<span>'+fa(open)+'</span></button>'+Object.entries(departments).map(([id,[label,glyph]])=>'<button type="button" data-dept="'+id+'" aria-pressed="'+(department===id)+'">'+icon(glyph)+label+'<span>'+fa(counts[id]||0)+'</span></button>').join('')+'<button type="button" class="dept-escalated" data-escalated aria-pressed="'+escalated+'">'+icon('shield')+'ارجاع به مدیر<span>'+fa(summary?.escalated||0)+'</span></button>';
  }
  function paintList(){
    const {list}=frame(),pages=Math.max(1,Math.ceil(total/25));
    list.innerHTML=rows.length?'<div class="staff-bulk-tools"><label class="check-all"><input type="checkbox" data-ticket-select-all>همهٔ این صفحه</label><span class="bulk-count" data-bulk-count>انتخاب نشده</span><span class="bulk-actions"><button class="btn btn-sm" type="button" data-bulk-status="closed">بستن منتخب</button><button class="btn btn-sm" type="button" data-bulk-status="open">باز کردن منتخب</button><button class="btn btn-sm btn-icon" type="button" data-copy-tickets title="کپی شناسه‌های منتخب" aria-label="کپی شناسه‌های منتخب">'+icon('copy')+'</button></span></div><ul class="ticket-list">'+rows.map(t=>'<li class="ticket-entry is-'+esc(t.status)+(ticket?.id===t.id?' is-active':'')+'"><input type="checkbox" value="'+esc(t.id)+'" data-ticket-code="'+esc(t.admin_code||t.id)+'" data-ticket-check aria-label="انتخاب تیکت '+esc(t.subject)+'"><button type="button" class="ticket-row" data-ticket="'+esc(t.id)+'"'+(ticket?.id===t.id?' aria-current="true"':'')+'><span class="ticket-top"><strong>'+esc(t.subject)+'</strong><time datetime="'+new Date(Number(t.updated_at)).toISOString()+'" title="'+esc(date(t.updated_at))+'">'+esc(ago(t.updated_at))+'</time></span><span class="ticket-meta"><span class="badge '+esc(t.status)+'">'+esc(statuses[t.status])+'</span><span class="tag tag--dept">'+esc(departments[t.department]?.[0]||'عمومی')+'</span>'+(t.escalated_at?'<span class="tag tag--escalated">نزد مدیر</span>':'')+(t.priority==='high'?'<span class="tag tag--high">اولویت بالا</span>':'')+'<bdi class="code">'+esc(t.admin_code||t.id.slice(0,8))+'</bdi></span></button></li>').join('')+'</ul>':'<div class="desk-empty"><b>گفت‌وگویی پیدا نشد</b><p>جست‌وجو یا وضعیت را تغییر بده.</p></div>';
    list.insertAdjacentHTML('beforeend','<nav class="pagination" aria-label="صفحه‌های تیکت"><button class="btn btn-sm" type="button" data-page="'+(page-1)+'" '+(page===1?'disabled':'')+'>قبلی</button><span>صفحهٔ '+fa(page)+' از '+fa(pages)+' · '+fa(total)+' تیکت</span><button class="btn btn-sm" type="button" data-page="'+(page+1)+'" '+(page*25>=total?'disabled':'')+'>بعدی</button></nav>');
  }
  function paintEmpty(){const {thread}=frame();workspace.classList.remove('is-reading');thread.innerHTML='<div class="desk-empty desk-empty--thread">'+icon('mail')+'<b>یک گفت‌وگو را انتخاب کن</b><p>پیام‌ها، مشخصات کاربر و پاسخ‌نویس این‌جا باز می‌شوند.</p></div>';}
  async function list(keepThread=false){
    if(busy)return;const token=++serial;workspace.setAttribute('aria-busy','true');
    const params=new URLSearchParams({staff:'1',page,q:filters.elements.q.value,status:filters.elements.status.value,department});if(escalated)params.set('escalated','1');
    try{const data=await request('?'+params);if(token!==serial)return;rows=data.rows;total=data.total;summary=data.summary;paintSummary();paintList();if(!keepThread||!ticket){ticket=null;paintEmpty();}}
    catch(e){if(token===serial)error(e);}finally{if(token===serial)workspace.setAttribute('aria-busy','false');}
  }
  function bubble(m,i,data){
    const staff=!!m.staff;if(m.internal)return '<article class="message internal"><header><span class="who">'+icon('lock')+'یادداشت داخلی'+(m.author?' · '+esc(m.author):'')+'</span><time title="'+esc(date(m.created_at))+'">'+esc(ago(m.created_at))+'</time></header><p>'+esc(m.body)+'</p><div class="files" data-files="'+i+'"></div></article>';
    return '<article class="message'+(staff?' staff':'')+'"><header><span class="who">'+(staff?icon('shield')+(m.author?esc(m.author):'پشتیبانی'):icon('user')+esc(data.customer?.name||'کاربر'))+'</span><time title="'+esc(date(m.created_at))+'">'+esc(ago(m.created_at))+'</time></header><p>'+esc(m.body)+'</p><div class="files" data-files="'+i+'"></div></article>';
  }
  async function open(id,{focus=true}={}){
    const token=++serial;workspace.setAttribute('aria-busy','true');feedback.textContent='';
    try{const data=await request('?staff=1&id='+encodeURIComponent(id));if(token!==serial)return;ticket=data;replyId=crypto.randomUUID();
      const {thread}=frame();workspace.classList.add('is-reading');
      workspace.querySelectorAll('.ticket-entry').forEach(li=>{const on=li.querySelector('[data-ticket]').dataset.ticket===id;li.classList.toggle('is-active',on);on?li.querySelector('[data-ticket]').setAttribute('aria-current','true'):li.querySelector('[data-ticket]').removeAttribute('aria-current');});
      const code=data.admin_code||data.id.slice(0,8),closed=data.status==='closed';
      thread.innerHTML='<div class="thread"><div class="thread-head"><button class="btn btn-sm btn-ghost thread-back" type="button" data-back>'+icon('menu')+'همهٔ تیکت‌ها</button><div class="thread-title"><h2>'+esc(data.subject)+'</h2><p><span class="badge '+esc(data.status)+'">'+esc(statuses[data.status])+'</span><span class="tag tag--dept">'+icon(departments[data.department]?.[1]||'mail')+'بخش '+esc(departments[data.department]?.[0]||'عمومی')+'</span><span class="tag">'+esc(categories[data.category]||'سایر')+'</span>'+(data.priority==='high'?'<span class="tag tag--high">اولویت بالا</span>':'')+'<button type="button" class="code code-copy" data-copy-ticket="'+esc(code)+'" title="کپی شناسهٔ تیکت">'+icon('copy')+'<bdi>'+esc(code)+'</bdi></button></p><small>ثبت '+esc(date(data.created_at))+' · '+fa(data.messages.filter(m=>!m.internal).length)+' پیام</small></div><div class="thread-actions"><button class="btn btn-sm" type="button" data-transfer>'+icon('refresh')+'انتقال به بخش</button>'+(data.escalated_at?'':'<button class="btn btn-sm" type="button" data-escalate>'+icon('shield')+'ارجاع به مدیر</button>')+'<button class="btn btn-sm '+(closed?'btn-primary':'')+'" type="button" data-status="'+(closed?'open':'closed')+'">'+icon(closed?'undo':'check')+(closed?'باز کردن دوباره':'بستن تیکت')+'</button></div></div>'+
        (data.escalated_at?'<div class="escalation" role="note">'+icon('shield')+'<div><b>ارجاع‌شده به مدیر · '+esc(ago(data.escalated_at))+'</b><p>'+esc(data.escalation_note||'')+'</p></div>'+(admin?'<button class="btn btn-sm btn-primary" type="button" data-escalation-done>'+icon('check')+'پیگیری انجام شد</button>':'<span class="escalation__wait">منتظر پیگیری مدیر</span>')+'</div>':'')+
        (data.customer?'<div class="customer"><span class="avatar" aria-hidden="true">'+esc((data.customer.name||'ک').trim().charAt(0))+'</span><div><strong>'+esc(data.customer.name||'بدون نام')+'</strong><small dir="ltr">'+esc(data.customer.admin_code||data.customer.id)+'</small></div><span class="badge '+(data.customer.suspended?'suspended':'active')+'">'+esc(data.customer.suspended?'حساب تعلیق‌شده':'حساب فعال')+'</span><button class="btn btn-sm btn-primary" type="button" data-profile>'+icon('user')+'پروندهٔ کاربر</button></div>':'')+
        '<div class="conversation">'+data.messages.map((m,i)=>bubble(m,i,data)).join('')+'</div>'+
        (closed?'<p class="thread-closed">'+icon('lock')+'این تیکت بسته است. برای پاسخ، اول آن را دوباره باز کن.</p>':'<div class="composer'+(mode==='note'?' is-note':'')+'"><div class="composer-mode" role="radiogroup" aria-label="نوع پیام"><button type="button" role="radio" data-mode="reply" aria-checked="'+(mode==='reply')+'">'+icon('mail')+'پاسخ به کاربر</button><button type="button" role="radio" data-mode="note" aria-checked="'+(mode==='note')+'">'+icon('lock')+'یادداشت داخلی</button></div><div class="canned" aria-label="شروع آماده">'+canned.map(([label],i)=>'<button type="button" class="chip" data-canned="'+i+'">'+esc(label)+'</button>').join('')+'</div><form class="reply" id="reply"><label for="reply-body" class="sr">پاسخ شما</label><textarea id="reply-body" name="body" required maxlength="6000" rows="4" placeholder="پاسخ به '+esc(data.customer?.name||'کاربر')+'… (Ctrl+Enter برای ارسال)"></textarea><div class="reply-foot"><span class="counter" data-counter>۰ / ۶٬۰۰۰</span><button class="btn btn-primary" type="submit">'+icon(mode==='note'?'lock':'mail')+(mode==='note'?'ثبت یادداشت':'ارسال پاسخ')+'</button></div></form></div>')+'</div>';
      thread.querySelectorAll('[data-files]').forEach(el=>{el.innerHTML=ResumeSupportFiles.links(data.messages[Number(el.dataset.files)].attachments,true);});
      thread.querySelector('#reply .reply-foot')?.insertAdjacentHTML('beforebegin',ResumeSupportFiles.input(true));
      const convo=thread.querySelector('.conversation');convo.scrollTop=convo.scrollHeight;
      if(focus)(thread.querySelector('#reply-body')||thread.querySelector('[data-back]'))?.focus({preventScroll:true});
      if(matchMedia('(max-width:980px)').matches)thread.scrollIntoView({block:'start'});
    }catch(e){if(token===serial)error(e);}finally{if(token===serial)workspace.setAttribute('aria-busy','false');}
  }
  function selected(){return [...workspace.querySelectorAll('[data-ticket-check]:checked')];}
  function countSelected(){const n=selected().length,label=workspace.querySelector('[data-bulk-count]');if(label)label.textContent=n?fa(n)+' انتخاب‌شده':'انتخاب نشده';}

  let timer=0;filters.elements.q.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(()=>{page=1;list(true);},350);});
  filters.onsubmit=e=>{e.preventDefault();clearTimeout(timer);page=1;list(true);};filters.elements.status.onchange=()=>{page=1;list(true);};
  $('#summary').addEventListener('click',e=>{const tile=e.target.closest('[data-filter]');if(!tile||busy)return;filters.elements.status.value=tile.dataset.filter;page=1;list(true);});
  $('#staff-refresh').addEventListener('click',async()=>{await list(true);if(ticket)await open(ticket.id,{focus:false});note('فهرست به‌روز شد.');});
  workspace.addEventListener('change',e=>{if(e.target.matches('[data-ticket-select-all]'))workspace.querySelectorAll('[data-ticket-check]').forEach(input=>input.checked=e.target.checked);if(e.target.matches('[data-ticket-check],[data-ticket-select-all]'))countSelected();});
  workspace.addEventListener('input',e=>{if(e.target.id!=='reply-body')return;const c=workspace.querySelector('[data-counter]');if(c){c.textContent=fa(e.target.value.length)+' / ۶٬۰۰۰';c.classList.toggle('is-near',e.target.value.length>5400);}});
  workspace.addEventListener('keydown',e=>{if(e.target.id==='reply-body'&&e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();e.target.form.requestSubmit();}});
  workspace.addEventListener('click',async e=>{
    const copy=e.target.closest('[data-copy-ticket]'),copySelected=e.target.closest('[data-copy-tickets]'),batch=e.target.closest('[data-bulk-status]'),cannedButton=e.target.closest('[data-canned]');
    if(cannedButton){const box=workspace.querySelector('#reply-body'),text=canned[Number(cannedButton.dataset.canned)][1];box.value=box.value?box.value.replace(/\s*$/,'\n')+text:text;box.dispatchEvent(new Event('input',{bubbles:true}));box.focus();return;}
    if(copy||copySelected){const ids=copy?[copy.dataset.copyTicket]:selected().map(x=>x.dataset.ticketCode||x.value);if(!ids.length){note('ابتدا تیکت‌ها را انتخاب کن');return;}try{await navigator.clipboard.writeText(ids.join('\n'));note(ids.length>1?fa(ids.length)+' شناسه کپی شد':'شناسه کپی شد');}catch{error(Error('کپی ممکن نشد؛ شناسه را انتخاب و کپی کن'));}return;}
    if(batch&&!busy){const ids=selected().map(x=>x.value);if(!ids.length){note('ابتدا تیکت‌ها را انتخاب کن');return;}const dialog=document.createElement('dialog');dialog.className='staff-bulk-dialog';dialog.innerHTML='<form><h2>'+esc(batch.textContent)+'</h2><p>'+fa(ids.length)+' تیکت انتخاب شده؛ نتیجهٔ هر مورد جداگانه ثبت می‌شود.</p><label>برای تأیید، تعداد را با ارقام انگلیسی بنویس<input name="count" required inputmode="numeric" autocomplete="off"></label><div class="dialog-actions"><button class="btn btn-primary" type="submit">اجرا</button><button class="btn" type="button" data-cancel>انصراف</button></div><p role="status"></p></form>';document.body.append(dialog);let pending=false;dialog.oncancel=event=>{if(pending)event.preventDefault();};dialog.onclose=()=>dialog.remove();dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();
      dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();if(pending)return;const form=event.target,status=form.querySelector('[role=status]');if(form.elements.count.value!==String(ids.length)){status.textContent='تعداد را دقیق وارد کن';return;}pending=busy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);let ok=0;const failures=[];for(const id of ids){try{await request('/status?staff=1',{id,status:batch.dataset.bulkStatus});ok++;}catch(err){failures.push(id+': '+err.message);}}pending=busy=false;await list(true);if(ticket&&ids.includes(ticket.id))await open(ticket.id,{focus:false});status.textContent=fa(ok)+' موفق، '+fa(failures.length)+' ناموفق'+(failures.length?'\n'+failures.join('\n'):'');form.querySelector('[type=submit]').remove();form.querySelector('[data-cancel]').disabled=false;form.querySelector('[data-cancel]').textContent='بستن';};dialog.showModal();return;}
    const modeButton=e.target.closest('[data-mode]');
    if(modeButton&&ticket){const box=workspace.querySelector('#reply-body'),draft=box?.value||'';mode=modeButton.dataset.mode;await open(ticket.id,{focus:false});const next=workspace.querySelector('#reply-body');if(next){next.value=draft;next.dispatchEvent(new Event('input',{bubbles:true}));next.focus();}return;}
    if(e.target.closest('[data-transfer]')&&ticket){transfer();return;}
    if(e.target.closest('[data-escalate]')&&ticket){escalate(false);return;}
    if(e.target.closest('[data-escalation-done]')&&ticket){escalate(true);return;}
    if(e.target.closest('[data-profile]')&&ticket){profile(ticket.user_id);return;}
    if(busy)return;const row=e.target.closest('[data-ticket]'),paging=e.target.closest('[data-page]'),state=e.target.closest('[data-status]');
    if(row)open(row.dataset.ticket);
    if(paging&&!paging.disabled){page=Number(paging.dataset.page);list(true);workspace.querySelector('.desk-list')?.scrollIntoView({block:'start'});}
    if(e.target.closest('[data-back]')){const last=ticket?.id;ticket=null;paintEmpty();workspace.querySelectorAll('.ticket-entry.is-active').forEach(li=>{li.classList.remove('is-active');li.querySelector('[data-ticket]').removeAttribute('aria-current');});workspace.querySelector('[data-ticket="'+last+'"]')?.focus();list(true);}
    if(state&&ticket){busy=true;state.disabled=true;try{await request('/status?staff=1',{id:ticket.id,status:state.dataset.status});busy=false;await open(ticket.id,{focus:false});await list(true);note(state.dataset.status==='closed'?'تیکت بسته شد.':'تیکت دوباره باز شد.');}catch(err){error(err);}finally{busy=false;state.disabled=false;}}
  });
  workspace.addEventListener('submit',async e=>{
    if(e.target.id!=='reply')return;e.preventDefault();if(busy)return;busy=true;const button=e.target.querySelector('button');button.disabled=true;
    try{if(mode==='note'){await request('/note?staff=1',{id:ticket.id,body:e.target.elements.body.value,requestId:replyId});busy=false;await open(ticket.id,{focus:false});note('یادداشت داخلی ثبت شد؛ کاربر آن را نمی‌بیند.');return;}
      const attachments=await ResumeSupportFiles.read(e.target.querySelector('#ticket-files'),true);await request('/reply?staff=1',{id:ticket.id,body:e.target.elements.body.value,requestId:replyId,attachments});busy=false;await open(ticket.id,{focus:false});await list(true);note('پاسخ ثبت شد.');}catch(err){error(err);}finally{busy=false;button.disabled=false;}
  });
  $('#departments').addEventListener('click',e=>{const b=e.target.closest('[data-dept],[data-escalated]');if(!b||busy)return;escalated=b.hasAttribute('data-escalated');department=escalated?'':b.dataset.dept;page=1;list(true);});

  // Small form dialogs: one request id per dialog so a double submit or a retry is applied once.
  function formDialog(title,fields,submitLabel,action,{wide=false}={}){
    const dialog=document.createElement('dialog');dialog.className='staff-bulk-dialog'+(wide?' staff-dialog--wide':'');const requestId=crypto.randomUUID();
    dialog.innerHTML='<form><h2>'+title+'</h2>'+fields+'<div class="dialog-actions"><button class="btn btn-primary" type="submit">'+submitLabel+'</button><button class="btn" type="button" data-cancel>انصراف</button></div><p role="status" class="dialog-status"></p></form>';
    document.body.append(dialog);let pending=false;dialog.oncancel=event=>{if(pending)event.preventDefault();};dialog.onclose=()=>dialog.remove();dialog.querySelector('[data-cancel]').onclick=()=>dialog.close();
    dialog.querySelector('form').onsubmit=async event=>{event.preventDefault();if(pending)return;const form=event.target,status=form.querySelector('[role=status]');pending=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);status.textContent='در حال ثبت…';
      try{await action(form.elements,requestId);dialog.close();}catch(err){status.textContent=err.message;status.dataset.kind='error';}finally{pending=false;form.querySelectorAll('button').forEach(b=>b.disabled=false);}};
    dialog.showModal();dialog.querySelector('select,input,textarea')?.focus();return dialog;
  }
  function transfer(){
    formDialog('انتقال تیکت به بخش دیگر','<p>تیکت در بخش «'+esc(departments[ticket.department]?.[0]||'عمومی')+'» است. انتقال به‌صورت یادداشت داخلی ثبت می‌شود و کاربر فقط بخش تازه را می‌بیند.</p><label>بخش مقصد<select name="department" required>'+Object.entries(departments).filter(([id])=>id!==ticket.department).map(([id,[label]])=>'<option value="'+id+'">'+label+'</option>').join('')+'</select></label><label>توضیح برای همکار (اختیاری)<textarea name="note" maxlength="500" rows="3" placeholder="مثلاً: کد رهگیری پرداخت در پیام دوم است"></textarea></label>','انتقال',async(f,requestId)=>{await request('/transfer?staff=1',{id:ticket.id,department:f.department.value,note:f.note.value,requestId});await open(ticket.id,{focus:false});await list(true);note('تیکت به بخش '+departments[f.department.value][0]+' منتقل شد.');});
  }
  function escalate(resolve){
    if(resolve)formDialog('پیگیری ارجاع','<p>ارجاع بسته می‌شود و تیکت به صف عادی برمی‌گردد.</p><label>نتیجهٔ پیگیری (اختیاری)<textarea name="note" maxlength="500" rows="3"></textarea></label>','ثبت پیگیری',async(f,requestId)=>{await request('/escalate?staff=1',{id:ticket.id,resolve:true,note:f.note.value,requestId});await open(ticket.id,{focus:false});await list(true);note('پیگیری ثبت شد.');});
    else formDialog('ارجاع به مدیر','<p>مدیرها اعلان می‌گیرند و تیکت در صف «ارجاع به مدیر» می‌ماند تا پیگیری شود. کاربر این ارجاع را نمی‌بیند.</p><label>چه چیزی باید پیگیری شود؟<textarea name="note" required minlength="5" maxlength="500" rows="4" placeholder="مثلاً: مبلغ از حساب کم شده ولی درگاه تأیید نکرده؛ بررسی در پنل بانک لازم است"></textarea></label>','ارجاع',async(f,requestId)=>{await request('/escalate?staff=1',{id:ticket.id,note:f.note.value,requestId});await open(ticket.id,{focus:false});await list(true);note('تیکت به مدیر ارجاع شد.');});
  }

  // Customer file: account, wallet (with credit), payments and invoices, pages and other tickets, in tabs.
  const paymentStatus={paid:['پرداخت‌شده','ok'],pending:['در انتظار','wait'],failed:['ناموفق','bad'],cancelled:['لغوشده','bad'],expired:['منقضی','bad']};
  // Council rule: staff refund a template, link theme, font or palette from this customer's ticket within 72 hours of purchase.
  function refundForm(data,u){
    const open=(data.purchases||[]).filter(p=>p.price>0&&/^(rt|lt|font|pal):/.test(p.ref)&&Date.now()-p.at<=72*36e5);
    if(ticket?.user_id!==u.id)return '<p class="cf-empty cf-refund-hint">'+icon('info')+'بازگشت وجه فقط از داخل تیکت همین کاربر انجام می‌شود.</p>';
    return '<form class="cf-credit cf-refund" data-refund><h3>'+icon('refresh')+'بازگشت وجه خرید</h3><p>فقط قالب، قالب لینک، فونت یا پالتی که تا ۷۲ ساعت پیش خریده شده و در هیچ صفحه‌ای انتخاب نشده. مبلغ فقط به کیف پول It برمی‌گردد؛ هر کاربر حداکثر دو بار در ۹۰ روز. اشتراک‌ها بازگشت ندارند.</p>'+(open.length?'<div class="cf-credit__row"><label>مورد<select name="ref" required><option value="">انتخاب کن</option>'+open.map(p=>'<option value="'+esc(p.ref)+'">'+esc(p.name)+' · '+it(p.price/2000)+'</option>').join('')+'</select></label><label>رمز حساب خودت<input name="password" type="password" autocomplete="current-password" placeholder="اگر رمز داری"></label></div><label>دلیل<input name="reason" required minlength="5" maxlength="500" placeholder="مثلاً: قالب را اشتباهی خرید و استفاده نکرد"></label>'+(admin?'<label class="cf-check"><input type="checkbox" name="override">عبور از سقف دو بار در ۹۰ روز (فقط مدیر، با دلیل)</label>':'')+'<div class="cf-credit__foot"><span></span><button class="btn btn-primary" type="submit">'+icon('refresh')+'بازگشت وجه</button></div>':'<p class="cf-empty">خریدی در ۷۲ ساعت گذشته نیست.</p>')+'<p role="status" class="dialog-status"></p></form>';
  }
  async function profile(userId){
    const dialog=document.createElement('dialog');dialog.className='customer-file';dialog.setAttribute('aria-labelledby','cf-title');
    dialog.innerHTML='<div class="cf-head"><h2 id="cf-title">پروندهٔ کاربر</h2><button class="btn btn-sm btn-icon" type="button" data-close aria-label="بستن">'+icon('x')+'</button></div><div class="cf-body"><p role="status" class="desk-state">در حال دریافت…</p></div>';
    document.body.append(dialog);dialog.onclose=()=>dialog.remove();dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.showModal();
    const body=dialog.querySelector('.cf-body');
    const paint=async(tab='account')=>{
      let data;try{data=await request('/customer?staff=1&id='+encodeURIComponent(userId));}catch(err){body.innerHTML='<p class="dialog-status" data-kind="error">'+esc(err.message)+'</p>';return;}
      const u=data.user,name=u.name||[u.first_name,u.last_name].filter(Boolean).join(' ')||'بدون نام';
      const row=(k,v)=>'<div><dt>'+k+'</dt><dd>'+v+'</dd></div>';
      const tabs=[['account','حساب','user'],['wallet','کیف پول','card'],['payments','پرداخت و فاکتور','receipt'],['pages','صفحه‌ها','resume'],['tickets','تیکت‌ها','mail']];
      const panels={
        account:'<dl class="cf-grid">'+row('نام',esc(name))+row('شمارهٔ موبایل','<bdi dir="ltr">'+esc(u.phone||'—')+'</bdi> '+(u.phone_verified?'<span class="tag tag--ok">تأییدشده</span>':'<span class="tag tag--high">تأییدنشده</span>'))+row('ایمیل',u.email?'<bdi dir="ltr">'+esc(u.email)+'</bdi> '+(u.email_verified?'<span class="tag tag--ok">تأییدشده</span>':''):'—')+row('عضویت',u.created_at?esc(date(u.created_at)):'—')+row('ورود با',u.social.length?esc(u.social.join('، ')):'شماره و رمز')+row('نشست‌های فعال',fa(u.sessions))+row('وضعیت حساب',u.suspended?'<span class="tag tag--high">تعلیق‌شده</span>':'<span class="tag tag--ok">فعال</span>')+row('انتشار',u.publication_blocked?'<span class="tag tag--high">مسدود</span>':'مجاز')+row('اشتراک',data.plan?'فعال تا '+esc(date(data.plan.end)):'ندارد')+row('خریدها',data.purchases.length?esc(data.purchases.map(p=>p.name).join('، ')):'—')+'</dl><p class="cf-id">شناسه: <bdi dir="ltr">'+esc(u.id)+'</bdi></p>',
        wallet:'<div class="cf-balance"><span>موجودی فعلی</span><strong>'+it(data.wallet.balance)+'</strong><small>'+toman(data.wallet.balance*2000)+'</small></div>'+
          '<form class="cf-credit" data-credit><h3>'+icon('plus')+'افزایش موجودی</h3><p>برای جبران پرداخت ناموفق یا خطای سیستم. دلیل در تاریخچهٔ کیف پول کاربر و گزارش مدیریت ثبت می‌شود'+(admin?'.':'؛ سقف هر شارژ '+it(data.creditLimits.each/2000)+' و سقف ۲۴ ساعت '+it(data.creditLimits.daily/2000)+' است.')+'</p><div class="cf-credit__row"><label>مقدار (It)<input name="amount" type="number" min="1" step="1" required inputmode="numeric"></label><label>رمز حساب خودت<input name="password" type="password" autocomplete="current-password" placeholder="اگر رمز داری"></label></div><label>دلیل<input name="reason" required minlength="5" maxlength="500" placeholder="مثلاً: پرداخت ۱۲۳۴ کم شد ولی شارژ نشد"></label><div class="cf-credit__foot"><span data-credit-preview></span><button class="btn btn-primary" type="submit">'+icon('plus')+'شارژ کیف پول</button></div><p role="status" class="dialog-status"></p></form>'+refundForm(data,u)+
          '<h3 class="cf-sub">آخرین تراکنش‌ها</h3>'+(data.wallet.transactions.length?'<ul class="cf-list">'+data.wallet.transactions.map(t=>'<li><span>'+esc(t.label)+'<small>'+esc(date(t.at))+'</small></span><b class="'+(t.amount<0?'neg':'pos')+'">'+(t.amount>0?'+':'')+it(t.amount)+'</b></li>').join('')+'</ul>':'<p class="cf-empty">تراکنشی ثبت نشده.</p>'),
        payments:'<h3 class="cf-sub">پرداخت‌های بانکی</h3>'+(data.payments.length?'<ul class="cf-list">'+data.payments.map(p=>{const [label,kind]=paymentStatus[p.status]||[p.status,'wait'];return '<li><span>'+toman(p.amount)+' · '+(p.provider==='sep'?'سپ':'زیبال')+'<small>'+esc(date(p.at))+(p.rrn?' · مرجع <bdi dir="ltr">'+esc(p.rrn)+'</bdi>':'')+(p.trace?' · پیگیری <bdi dir="ltr">'+esc(p.trace)+'</bdi>':'')+'</small></span><span class="tag tag--'+kind+'">'+esc(label)+'</span></li>';}).join('')+'</ul>':'<p class="cf-empty">پرداختی ثبت نشده.</p>')+
          '<h3 class="cf-sub">پیش‌فاکتورها</h3>'+(data.invoices.length?'<ul class="cf-list">'+data.invoices.map(i=>'<li><span>'+toman(i.amount)+'<small>'+esc(date(i.at))+' · <bdi dir="ltr">'+esc(i.id.slice(0,8))+'</bdi></small></span><span class="tag tag--'+(i.paid?'ok':i.expires<Date.now()?'bad':'wait')+'">'+(i.paid?'پرداخت‌شده':i.expires<Date.now()?'منقضی':'باز')+'</span></li>').join('')+'</ul>':'<p class="cf-empty">پیش‌فاکتوری ثبت نشده.</p>'),
        pages:data.pages.length?'<ul class="cf-list">'+data.pages.map(p=>'<li><span>صفحهٔ '+fa(p.slot)+(p.slug?' · <bdi dir="ltr">'+esc(p.slug)+'</bdi>':'')+'<small>قالب '+esc(p.template||'—')+' · نسخهٔ '+fa(p.revision)+'</small></span><span><span class="tag tag--'+(p.resume?'ok':'wait')+'">رزومه '+(p.resume?'منتشرشده':'منتشرنشده')+'</span> <span class="tag tag--'+(p.links?'ok':'wait')+'">لینک‌ها '+(p.links?'منتشرشده':'منتشرنشده')+'</span>'+(p.slug&&p.resume?' <a class="btn btn-sm" href="/u/'+encodeURIComponent(p.slug)+'/" target="_blank" rel="noopener">'+icon('external')+'مشاهده</a>':'')+'</span></li>').join('')+'</ul>':'<p class="cf-empty">صفحه‌ای ساخته نشده.</p>',
        tickets:'<ul class="cf-list">'+data.tickets.map(t=>'<li><span>'+esc(t.subject)+'<small>'+esc(departments[t.department]?.[0]||'عمومی')+' · '+esc(ago(t.updated_at))+'</small></span><span><span class="badge '+esc(t.status)+'">'+esc(statuses[t.status])+'</span>'+(t.id===ticket?.id?'':' <button class="btn btn-sm" type="button" data-open-ticket="'+esc(t.id)+'">باز کردن</button>')+'</span></li>').join('')+'</ul>'};
      dialog.querySelector('#cf-title').innerHTML=icon('user')+esc(name);
      body.innerHTML='<div class="cf-tabs" role="tablist">'+tabs.map(([id,label,glyph])=>'<button type="button" role="tab" data-cf-tab="'+id+'" aria-selected="'+(id===tab)+'">'+icon(glyph)+label+'</button>').join('')+'</div><div class="cf-panel" role="tabpanel">'+panels[tab]+'</div>';
      const refund=body.querySelector('[data-refund]');
      if(refund){const requestId=crypto.randomUUID();refund.onsubmit=async event=>{event.preventDefault();const status=refund.querySelector('[role=status]'),opt=refund.elements.ref.selectedOptions[0];if(!opt?.value){status.textContent='مورد را انتخاب کن';return;}
          if(!confirm('مبلغ «'+opt.textContent+'» به کیف پول '+name+' برگردد و دسترسی‌اش برداشته شود؟'))return;refund.querySelectorAll('button,input,select').forEach(x=>x.disabled=true);status.textContent='در حال بازگشت وجه…';
          try{const r=await request('/refund?staff=1',{userId,ticketId:ticket.id,ref:opt.value,reason:refund.elements.reason.value,password:refund.elements.password.value||undefined,override:admin&&refund.elements.override?.checked||undefined,requestId});note(it(r.amount)+' به کیف پول '+name+' برگشت.');await paint('wallet');}
          catch(err){status.textContent=err.message;status.dataset.kind='error';refund.querySelectorAll('button,input,select').forEach(x=>x.disabled=false);}};}
      const credit=body.querySelector('[data-credit]');
      if(credit){const requestId=crypto.randomUUID(),preview=credit.querySelector('[data-credit-preview]');credit.elements.amount.oninput=()=>{const n=Number(credit.elements.amount.value);preview.textContent=n>0?'= '+toman(n*2000)+' · موجودی بعدی '+it(data.wallet.balance+n):'';};
        credit.onsubmit=async event=>{event.preventDefault();const status=credit.querySelector('[role=status]'),n=Number(credit.elements.amount.value);if(!Number.isSafeInteger(n)||n<1){status.textContent='مقدار را به عدد صحیح It بنویس';return;}
          if(!confirm(it(n)+' به کیف پول '+name+' اضافه شود؟'))return;credit.querySelectorAll('button,input').forEach(x=>x.disabled=true);status.textContent='در حال شارژ…';
          try{await request('/credit?staff=1',{userId,ticketId:ticket?.user_id===userId?ticket.id:undefined,toman:n*2000,reason:credit.elements.reason.value,password:credit.elements.password.value||undefined,requestId});note(it(n)+' به کیف پول '+name+' اضافه شد.');await paint('wallet');if(ticket)open(ticket.id,{focus:false});}
          catch(err){status.textContent=err.message;status.dataset.kind='error';credit.querySelectorAll('button,input').forEach(x=>x.disabled=false);}};}
    };
    body.addEventListener('click',e=>{const t=e.target.closest('[data-cf-tab]');if(t)paint(t.dataset.cfTab);const o=e.target.closest('[data-open-ticket]');if(o){dialog.close();open(o.dataset.openTicket);}});
    await paint();
  }
  $('#logout').onclick=async()=>{if(busy)return;try{const r=await fetch('/api/auth/logout',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!r.ok)throw Error('خروج انجام نشد');location.assign('/login/');}catch(e){error(e);}};
  // Quietly refresh the list every minute while the tab is visible and nothing is being typed or sent.
  setInterval(()=>{if(document.hidden||busy||document.querySelector('dialog[open]'))return;if(document.activeElement?.id==='reply-body'&&document.activeElement.value)return;list(true);},60000);
  (async()=>{icons();const r=await fetch('/api/auth/session'),{user}=await r.json();if(!user){location.replace('/login/');return;}if(!user.is_owner&&!user.is_admin&&!user.is_support){location.replace('/dashboard/');return;}owner=user.id;admin=!!(user.is_owner||user.is_admin);escalated=new URLSearchParams(location.search).get('escalated')==='1';$('#staff-name').textContent=[user.first_name,user.last_name].filter(Boolean).join(' ')||'پشتیبان ResumeIt';const role=user.is_owner?'مالک / فول ادمین':user.is_admin?'ادمین':'ساپورت';$('.staff-profile small').textContent=role;$('.role-badge').textContent='میز پشتیبانی · '+role;if(user.is_owner||user.is_admin)document.querySelector('[data-admin-only]').hidden=false;await list();const linked=new URLSearchParams(location.search).get('ticket');if(linked&&/^[a-f0-9-]{36}$/.test(linked))open(linked);})().catch(error);
})();
